/**
 * Installing the Hub.
 *
 * Three files a browser needs before it will offer "Add to Home Screen": a
 * manifest, icons it can actually fetch, and a service worker with a fetch
 * handler. All three are served from here, out of the same single bundled
 * function as everything else — no static directory, because naming one is what
 * flipped Vercel into static-site mode and broke a deploy once already.
 *
 * ── The service worker deliberately caches nothing ──────────────────────────
 *
 * A service worker exists here to satisfy the install requirement, and for no
 * other reason. The obvious next step — cache the dashboard so it opens
 * instantly — would mean a phone showing yesterday's stock and price as though
 * they were current. That is the exact failure this whole system is built to
 * refuse: a wrong reading presented confidently. So every request goes to the
 * network, and when the network is not there the app says so.
 */

/** Generated from the eye of the dnacardvault creature — a closeup of the
 * creature's actual eye, snipped from the logo, enlarged and enhanced,
 * over the logo's own DNA letterforms traced to vectors. One art, all sizes. */
export const ICONS: Record<string, string> = {
  '192':
    '',
  '512':
    '',
  'maskable':
    '',
};

export function iconResponse(name: string): Response | null {
  const b64 = ICONS[name];
  if (!b64) return null;
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  return new Response(bytes, {
    headers: {
      'Content-Type': 'image/png',
      // Icons are immutable for the life of a deploy; the filename changes when
      // the art does.
      'Cache-Control': 'public, max-age=604800, immutable',
    },
  });
}

/**
 * The manifest.
 *
 * `share_target` is the part that makes this worth installing. On Android,
 * sharing a Target link from Chrome offers "Hub" alongside the messaging apps,
 * and the link lands on /add ready to become a watched mission. iOS has no
 * share target, so there the flow is paste-into-the-box; the page handles both.
 */
export const MANIFEST = {
  name: 'Vault Watch — what is being watched',
  short_name: 'Vault Watch',
  description: 'Watch Pokémon TCG listings at Target, Pokémon Center and Walmart.',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  orientation: 'any',
  background_color: '#09080e',
  theme_color: '#09080e',
  categories: ['shopping', 'utilities'],
  icons: [
    { src: '/icon-192.png?v=4', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png?v=4', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/icon-maskable.png?v=4', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
  shortcuts: [
    { name: 'Add a listing', short_name: 'Add', url: '/add' },
  ],
  share_target: {
    action: '/add',
    method: 'GET',
    // Android puts a shared link in `url` sometimes and in `text` other times,
    // depending on the app doing the sharing. Take both and sort it out on the
    // page rather than trusting either.
    params: { title: 'title', text: 'text', url: 'url' },
  },
};

/**
 * The service worker. Network only, on purpose — see the note at the top.
 */
export const SERVICE_WORKER = `
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));

// No cache. Not an omission: a cached dashboard is a confident wrong answer,
// and this app exists to not give those.
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  event.respondWith(
    fetch(event.request).catch(
      () =>
        new Response(
          '<!doctype html><meta charset=utf-8>' +
          '<meta name=viewport content="width=device-width,initial-scale=1">' +
          '<body style="margin:0;display:grid;place-items:center;height:100vh;' +
          'background:#09080e;color:#9b97b0;font:400 15px/1.6 system-ui;text-align:center">' +
          '<div><strong style="color:#edebf5;display:block;margin-bottom:6px">Offline</strong>' +
          'Vault Watch shows live readings, so there is nothing useful to show ' +
          'without a connection.</div>',
          { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } },
        ),
    ),
  );
});
`;
